where mapper.ingredient_id=inserted.ingredient_id;

alter table public.mapper_basement
  drop constraint if exists mapper_basement_verification_status_check;
alter table public.mapper_basement
  drop constraint if exists mapper_basement_storage_type_check;
alter table public.mapper_basement
  add constraint mapper_basement_verification_status_check CHECK (verification_status = ANY (ARRAY['Blocked'::text, 'Estimated'::text, 'Estimated / Needs Label Review'::text, 'PI Calculated / Needs Label Review'::text, 'Superseded Duplicate'::text, 'Vegan verified / allergen label review required'::text, 'Vegan verified / cross-contamination noted'::text, 'Vegan/dairy-free verified / allergen label review required'::text, 'Verified'::text, 'Verified / Basis Check Needed'::text, 'Verified / Engine mapping review'::text, 'Verified / PI Calculated'::text, 'Verified / Public Label'::text, 'PI Calculated / Global Reference'::text, 'PI Calculated / Global DE Reference'::text, 'Verified / Global Reference'::text]));
alter table public.mapper_basement
  add constraint mapper_basement_storage_type_check CHECK (storage_type = ANY (ARRAY['ambient'::text, 'ambient_dry'::text, 'chilled'::text, 'fresh'::text, 'fresh_chilled'::text, 'frozen'::text, 'frozen_or_refrigerated'::text, 'refrigerated'::text]));

-- Restore the exact pre-sync central search definition captured from staging.
CREATE OR REPLACE FUNCTION public.search_products_v1(p_query text DEFAULT ''::text, p_context text DEFAULT 'BASE'::text, p_market_scope text DEFAULT 'my_markets_and_global'::text, p_selected_markets text[] DEFAULT '{}'::text[], p_favorites_only boolean DEFAULT false, p_product_profile text DEFAULT NULL::text, p_entity_kind text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_cursor integer DEFAULT 0, p_token_groups jsonb DEFAULT '[]'::jsonb)
 RETURNS TABLE(id uuid, current_version_id uuid, entity_kind text, status text, verification_method text, provenance text, display_name text, original_name text, original_language text, brand text, canonical_family text, category text, product_form text, mapped_ingredient_id text, markets text[], retailers text[], eans text[], aliases text[], favorite boolean, recently_used_at timestamp with time zone, usable_in_base boolean, main_allowed boolean, usable_as_topping boolean, blocked_reason text, missing_fields text[], invalid_fields text[], public_data jsonb, private_price numeric, private_currency text, relevance numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  with input as (
    select
      trim(regexp_replace(extensions.unaccent(lower(coalesce(p_query,''))),'[^a-z0-9]+',' ','g')) q,
      upper(coalesce(p_context,'BASE')) context,
      lower(coalesce(p_market_scope,'my_markets_and_global')) market_scope
  ), expanded as (
    select i.*,array(
      select distinct term from (
        select i.q term
        union all
        select public.gellatti_search_root(i.q)
        union all
        select a.normalized_alias from public.product_aliases a
        where i.q<>'' and (
          (a.normalized_alias % i.q and extensions.similarity(a.normalized_alias,i.q)>=0.45)
          or a.normalized_alias like i.q||'%'
          or i.q like a.normalized_alias||'%'
        )
      ) candidate_terms
      where term<>''
    )::text[] terms
    from input i
  ), mapper_candidates as (
    select
      p.id,p.current_version_id,'pi_base'::text entity_kind,'pi_base'::text status,
      case when lower(coalesce(m.verification_status,'')) like 'verified%' then 'mapper_verified' when lower(coalesce(m.verification_status,'')) like '%label review%' then 'mapper_needs_label_review' when lower(coalesce(m.verification_status,'')) like 'estimated%' or lower(coalesce(m.verification_status,'')) like 'pi calculated%' then 'mapper_estimated' else 'mapper_other' end::text verification_method,'mapper'::text provenance,
      coalesce(nullif(m.ingredient_name_display,''),m.ingredient_name_internal) display_name,
      nullif(m.ingredient_name_internal,'') original_name,null::text original_language,m.brand,
      coalesce(b.family_id,p.canonical_family) canonical_family,m.ingredient_category category,
      coalesce(b.form_id,m.ingredient_subcategory) product_form,m.ingredient_id mapped_ingredient_id,
      '{}'::text[] markets,'{}'::text[] retailers,
      array_remove(array[m.ean_code],null)::text[] eans,
      array_remove(array[
        m.ingredient_name_display,m.ingredient_name_internal,m.ingredient_category,
        m.ingredient_subcategory,b.family_id,b.subfamily_id,b.form_id
      ]||coalesce((select array_agg(a.alias) from public.product_aliases a
        where a.product_id=p.id),'{}'::text[]),null)::text[] aliases,
      (f.id is not null) favorite,ru.last_used_at recently_used_at,
      (m.is_active and coalesce(p.status,'')<>'rejected' and m.approved_for_base
        and public.canonical_module_product_role_v1(
          m.ingredient_category,m.ingredient_subcategory
        ) in ('BASE_ONLY','BASE_AND_TOPPING')) usable_in_base,
      (b.behavior_role in ('MAIN_ALLOWED','MAIN_PROFILE_SPECIFIC')
        and b.main_policy_status='COVERED'
        and (p_product_profile is null or b.profile_applicability ? p_product_profile)) main_allowed,
      (m.is_active and coalesce(p.status,'')<>'rejected' and m.approved_for_base
        and public.canonical_module_product_role_v1(
          m.ingredient_category,m.ingredient_subcategory
        ) in ('TOPPING_ONLY','BASE_AND_TOPPING')) usable_as_topping,
      case
        when e.context='BASE' and not (m.approved_for_base
            and public.canonical_module_product_role_v1(
              m.ingredient_category,m.ingredient_subcategory
            ) in ('BASE_ONLY','BASE_AND_TOPPING'))
          then 'Brak zatwierdzenia PINGÜINO Base'

        when e.context='TOPPING' and not (m.approved_for_base
            and public.canonical_module_product_role_v1(
              m.ingredient_category,m.ingredient_subcategory
            ) in ('TOPPING_ONLY','BASE_AND_TOPPING'))
          then 'Niedostępny jako topping'
        else null
      end blocked_reason,
      '{}'::text[] missing_fields,'{}'::text[] invalid_fields,
      jsonb_build_object('verificationStatus',m.verification_status,'productAccuracy',coalesce(m.data_confidence_percent,0),'sourceConfidence',coalesce(m.data_confidence_percent,0),'verificationSource',m.verification_source,'approvedForBase',m.approved_for_base,'approvedForEngines',m.approved_for_engines,'lifecycleRejected',coalesce(p.status,'')='rejected','carbonationStatus',m.carbonation_status,'carbonation',jsonb_build_object('status',m.carbonation_status,'evidence','[]'::jsonb,'decision','NO_EXACT_ASSERTION')) public_data,r.private_price,r.currency private_currency,
      (
        case when e.q='' then 1
          when exists(select 1 from unnest(e.terms) t where
            trim(regexp_replace(extensions.unaccent(lower(coalesce(m.ingredient_name_display,''))),'[^a-z0-9]+',' ','g'))=t)
            then 140
          when exists(select 1 from unnest(e.terms) t where
            concat_ws(' ',m.ingredient_name_display,m.ingredient_name_internal,m.ingredient_category,
              m.ingredient_subcategory,m.ingredient_id) ilike '%'||t||'%') then 100
          else 60 * extensions.similarity(
            trim(regexp_replace(extensions.unaccent(lower(concat_ws(' ',m.ingredient_name_display,
              m.ingredient_name_internal,m.ingredient_category,m.ingredient_subcategory))),'[^a-z0-9]+',' ','g')),
            e.q)
        end
        + case when e.context='BASE' then 25 else 8 end
        + case when lower(coalesce(b.form_id,m.ingredient_subcategory,'')) in ('fresh','fresh_fruit','puree','frozen') then 24 else 0 end
        + 0
        + case when f.id is not null then 8 else 0 end
      )::numeric relevance,
      trim(regexp_replace(extensions.unaccent(lower(concat_ws(' ',m.ingredient_name_display,
        m.ingredient_name_internal,m.ingredient_category,m.ingredient_subcategory,m.ingredient_id,
        b.family_id,b.subfamily_id,b.form_id,array_to_string(array(select a.alias
          from public.product_aliases a where a.product_id=p.id),' ')))),'[^a-z0-9]+',' ','g')) search_text,
      p.search_document indexed_search_text
    from expanded e
    join public.mapper_basement m on m.is_active
    join public.products p on p.product_kind='mapper_reference'
      and p.normalized_identity='mapper:'||m.ingredient_id
      and p.is_active and p.merged_into_product_id is null
    join public.product_versions v on v.id=p.current_version_id and v.product_id=p.id
    join public.product_behavior_bindings b on b.id=p.current_behavior_binding_id
      and b.product_id=p.id and b.product_version_id=v.id and b.is_current
    left join public.global_catalog_favorites f on f.user_id=auth.uid()
      and f.entity_kind='pi_base' and f.mapper_ingredient_id=m.ingredient_id
    left join public.global_catalog_recent_usage ru on ru.user_id=auth.uid()
      and ru.entity_kind='pi_base' and ru.mapper_ingredient_id=m.ingredient_id
    left join public.user_product_relations r on r.user_id=auth.uid() and r.product_id=p.id
  ), commercial_base as (
    select
      p.id,p.current_version_id,'commercial_product'::text entity_kind,
      p.canonical_verification_status status,p.canonical_verification_method verification_method,
      p.canonical_provenance provenance,
      p.product_name_display display_name,p.product_name_internal original_name,
      v.facts->>'originalLanguage' original_language,p.brand,p.canonical_family,
      p.product_category category,coalesce(b.form_id,v.facts#>>'{public_data,formId}') product_form,
      b.mapper_ingredient_id mapped_ingredient_id,
      array(select distinct x from unnest(array_remove(array[
        v.facts->>'market',v.facts#>>'{public_data,market}'
      ]||coalesce((select array_agg(coalesce(vm.market,pv.market)) from public.product_variants pv
        left join public.product_variant_markets vm on vm.variant_id=pv.id
        where pv.product_id=p.id and pv.is_current),'{}'::text[]),null)) x) markets,
      array(select distinct x from unnest(array_remove(array[
        v.facts->>'retailer',v.facts#>>'{public_data,retailer}'
      ]||coalesce((select array_agg(o.retailer) from public.product_variants pv
        join public.product_retailer_offers o on o.variant_id=pv.id
        where pv.product_id=p.id and pv.is_current),'{}'::text[]),null)) x) retailers,
      array(select distinct x from unnest(array_remove(array[p.ean_code_normalized]
        ||coalesce((select array_agg(pv.ean) from public.product_variants pv
          where pv.product_id=p.id and pv.is_current),'{}'::text[]),null)) x) eans,
      array(select distinct x from unnest(array_remove(array[
        p.product_name_display,p.product_name_internal,p.brand,p.canonical_family,p.product_category,
        b.family_id,b.subfamily_id,b.form_id
      ]||coalesce((select array_agg(a.alias) from public.product_aliases a
        where a.product_id=p.id),'{}'::text[]),null)) x) aliases,
      coalesce(r.favorite,false) favorite,r.recently_used_at,
      (coalesce(p.status,'')<>'rejected'
        and v.facts#>>'{productIntelligence,engineUsable}'='true'
        and jsonb_typeof(v.facts->'technicalComposition')='object'
        and v.facts->'technicalComposition'<>'{}'::jsonb
        and b.mapper_ingredient_id is null
        and coalesce((b.profile_permissions->>'BASE_RECIPE')::boolean,false)) usable_in_base,
      (b.behavior_role in ('MAIN_ALLOWED','MAIN_PROFILE_SPECIFIC')
        and b.main_policy_status='COVERED'
        and (p_product_profile is null or b.profile_applicability ? p_product_profile)) main_allowed,
      ((coalesce(p.status,'')<>'rejected' and m.ingredient_id is not null and m.is_active and m.approved_for_base)
        or (p.canonical_verification_status<>'blocked' and coalesce((b.profile_permissions->>'TOPPING')::boolean,false))) usable_as_topping,
      coalesce((select array_agg(x.value) from jsonb_array_elements_text(
        coalesce(v.facts->'missingFields','[]'::jsonb)) x(value)),'{}') missing_fields,
      coalesce((select array_agg(x.value) from jsonb_array_elements_text(
        coalesce(v.facts->'invalidFields','[]'::jsonb)) x(value)),'{}') invalid_fields,
      (coalesce(v.facts->'public_data',v.facts)||jsonb_build_object('productCode',p.product_code,'lifecycleRejected',coalesce(p.status,'')='rejected','approvedForBase',coalesce(m.approved_for_base,false),'approvedForEngines',coalesce(m.approved_for_engines,false))) public_data,r.private_price,r.currency private_currency,
      trim(regexp_replace(extensions.unaccent(lower(concat_ws(' ',p.product_code,p.product_name_display,
        p.product_name_internal,p.brand,p.canonical_family,p.product_category,b.family_id,b.subfamily_id,
        b.form_id,array_to_string(array(select a.alias from public.product_aliases a where a.product_id=p.id),' ')))),'[^a-z0-9]+',' ','g')) search_text,
      p.search_document indexed_search_text
    from public.products p
    join public.product_versions v on v.id=p.current_version_id and v.product_id=p.id
    join public.product_behavior_bindings b on b.id=p.current_behavior_binding_id
      and b.product_id=p.id and b.product_version_id=v.id and b.is_current
    left join public.mapper_basement m on m.ingredient_id=b.mapper_ingredient_id
    left join public.user_product_relations r on r.user_id=auth.uid() and r.product_id=p.id
    -- SOL052_PUBLICATION_ELIGIBILITY_SEARCH_V2
    where p.product_kind<>'mapper_reference' and p.is_active and p.merged_into_product_id is null
      and coalesce(p.canonical_verification_status, '') <> 'blocked'
      and ((p.visibility='shared' and
          public.product_publication_identity_eligible_v1(v.facts))
        or (p.visibility<>'shared' and (
          p.owning_account_id=auth.uid() or p.created_by=auth.uid()
          or exists(select 1 from public.product_ingest_events ev
            where ev.product_id=p.id and ev.actor_user_id=auth.uid())
          or exists(select 1 from public.customer_added_product_accounts linked
            where linked.product_id=p.id and linked.user_id=auth.uid()))))
  ), commercial_candidates as (
    select
      c.id,c.current_version_id,c.entity_kind,c.status,c.verification_method,c.provenance,
      c.display_name,c.original_name,c.original_language,c.brand,c.canonical_family,c.category,
      c.product_form,c.mapped_ingredient_id,c.markets,c.retailers,c.eans,c.aliases,c.favorite,
      c.recently_used_at,c.usable_in_base,c.main_allowed,c.usable_as_topping,
      case
        when coalesce((c.public_data->>'lifecycleRejected')::boolean,false) then 'product_rejected:'||c.id::text||':'||coalesce(c.mapped_ingredient_id,'none')||':'||coalesce(c.current_version_id::text,'none')||':'||e.context
        when e.context='BASE' and not c.usable_in_base then 'product_owned_profile_incomplete:'||c.id::text||':'||coalesce(c.current_version_id::text,'none')||':BASE_RECIPE'
        when e.context='TOPPING' and not c.usable_as_topping then 'module_permission_missing:'||c.id::text||':'||coalesce(c.mapped_ingredient_id,'none')||':'||coalesce(c.current_version_id::text,'none')||':TOPPING'
        else null
      end blocked_reason,
      c.missing_fields,c.invalid_fields,c.public_data,c.private_price,c.private_currency,
      (
        case when e.q='' then 1
          when exists(select 1 from unnest(e.terms) t where c.search_text=t) then 135
          when exists(select 1 from unnest(e.terms) t where c.search_text like '%'||t||'%') then 95
          else 60*extensions.similarity(c.search_text,e.q)
        end
        + case when c.favorite then 8 else 0 end
        + 0
        + case when cardinality(p_selected_markets)>0 and c.markets&&p_selected_markets then 6 else 0 end
        + case when c.retailers&&coalesce((select pref.preferred_retailers
            from public.account_product_market_preferences pref
            where pref.user_id=auth.uid()),'{}'::text[]) then 3 else 0 end
      )::numeric relevance,
      c.search_text,c.indexed_search_text
    from commercial_base c cross join expanded e
    where e.market_scope='global'
      or (e.market_scope='my_markets_and_global' and (
        cardinality(p_selected_markets)=0 or cardinality(c.markets)=0
        or c.markets&&p_selected_markets or c.markets&&array['GLOBAL']::text[]
      ))
      or (e.market_scope in ('my_markets','strict_market')
        and cardinality(p_selected_markets)>0 and c.markets&&p_selected_markets)
  ), candidates as (
    select * from mapper_candidates
    union all
    select * from commercial_candidates
  )
  select c.id,c.current_version_id,c.entity_kind,c.status,c.verification_method,c.provenance,
    c.display_name,c.original_name,c.original_language,c.brand,c.canonical_family,c.category,
    c.product_form,c.mapped_ingredient_id,c.markets,c.retailers,c.eans,c.aliases,c.favorite,
    c.recently_used_at,c.usable_in_base,c.main_allowed,c.usable_as_topping,c.blocked_reason,
    c.missing_fields,c.invalid_fields,c.public_data,c.private_price,c.private_currency,c.relevance
  from candidates c cross join expanded e
  where auth.uid() is not null
    and e.context in ('BASE','TOPPING')
    and e.market_scope in ('my_markets','my_markets_and_global','global','strict_market')
    and (p_entity_kind is null or c.entity_kind=p_entity_kind)
    and (not p_favorites_only or c.favorite)
    and (e.q=''
      or (' '||c.search_text||' ') like '% '||e.q||' %'
      or (nullif(regexp_replace(p_query,'\D','','g'),'') is not null
        and exists(select 1 from unnest(c.eans) x where x=regexp_replace(p_query,'\D','','g')))
      or public.gellatti_search_match_tier(
        c.display_name,c.original_name,c.brand,c.search_text,p_query,p_token_groups
      )>0)
  order by public.gellatti_search_match_tier(
      c.display_name,c.original_name,c.brand,c.search_text,p_query,p_token_groups
    ) desc,
    case when e.q<>'' then c.relevance - case when c.favorite then 8 else 0 end
      end desc nulls last,
    case when e.q='' then c.recently_used_at end desc nulls last,
    c.entity_kind='pi_base' desc,c.display_name,c.id
  offset greatest(coalesce(p_cursor,0),0)
  limit least(greatest(coalesce(p_limit,100),1),500);
$function$;

-- Remove only queue entries produced by this rollback transaction. Historical
-- queue rows from the snapshot are not rewritten or deleted.
delete from public.product_behavior_reclassification_queue queue
where queue.queued_at>=transaction_timestamp()
  and queue.entity_id in (
    select product_version_id::text from mapper_root_current_binding_preimage
    union
    select ingredient_id from mapper_current_binding_preimage
    union
    select preimage.payload->>'ingredient_id' from mapper_rollback_preimage preimage
    union
    select ingredient_id from mapper_rollback_inserted_ids
  )
  and queue.status in ('pending','queued');

do $postcheck$
begin
  if (select count(*) from public.mapper_basement where is_active)<>2147
    or (select count(distinct ingredient_id) from public.mapper_basement where is_active)<>2147
    or (select max(ingredient_id) from public.mapper_basement where is_active)<>'PI-ING-002172' then
    raise exception 'Rollback failed to restore the 2147/2147 Mapper prestate';
  end if;
  if exists(
    select 1
    from mapper_rollback_preimage preimage
    join public.mapper_basement mapper
      on mapper.ingredient_id=preimage.payload->>'ingredient_id'
    where (to_jsonb(mapper)-'created_at'-'updated_at')
      is distinct from (preimage.payload-'created_at'-'updated_at')
  ) then raise exception 'Rollback Mapper preimage mismatch'; end if;
  if exists(
    select 1 from mapper_rollback_preimage preimage
    where not exists(
      select 1 from public.mapper_basement mapper
      where mapper.ingredient_id=preimage.payload->>'ingredient_id'
    )
  ) then raise exception 'Rollback Mapper identity missing'; end if;
  if exists(
    select 1 from mapper_root_rollback_preimage preimage
    join public.products product on product.id=(preimage.payload->>'id')::uuid
    where not (to_jsonb(product) @> preimage.payload)
  ) then raise exception 'Rollback root preimage mismatch'; end if;
  if (select count(*) from public.products product
      join mapper_root_rollback_inserted_codes inserted using(product_code)
      where product.product_kind='mapper_reference'
        and not product.is_active and product.current_behavior_binding_id is null)<>452 then
    raise exception 'Rollback failed to soft-deactivate the 452 new roots';
  end if;
  if exists(select 1 from public.product_behavior_bindings
      where classifier_version='mapper-final-2541-2026-09-11-v1')
    or exists(select 1 from public.mapper_product_behavior_bindings
      where classifier_version='mapper-final-2541-2026-09-11-v1') then
    raise exception 'Release-specific bindings remain after rollback';
  end if;
  if (select count(*) from public.mapper_product_behavior_bindings binding
      join mapper_current_binding_preimage prior on prior.binding_id=binding.id
      where binding.is_current)<>2089 then
    raise exception 'Rollback failed to restore prior Mapper current bindings';
  end if;
  if (select count(*) from public.products product
      join mapper_root_current_binding_preimage prior
        on prior.product_id=product.id
       and prior.product_version_id=product.current_version_id
       and prior.binding_id=product.current_behavior_binding_id
      join public.product_behavior_bindings binding
        on binding.id=prior.binding_id and binding.is_current)<>2089 then
    raise exception 'Rollback failed to restore prior root pointers/current bindings';
  end if;
  if (select count(*) from public.mapper_process_metadata)<>2089 then
    raise exception 'Out-of-scope process metadata changed during rollback';
  end if;
end
$postcheck$;

notify pgrst,'reload schema';
commit;
